<!-- buttondown-editor-mode: fancy --><h3>Masters</h3><p>I am happy to announce that I finally decided on my masters program of choice. I will be going to <strong>RWTH Aachen into Software systems engineering program. </strong></p><p>I am excited to travel and explore other parts of Germany and long for lectures and studies. I have currently only been here for a few weeks but I have already discovered a lot about this city and the university!</p><h3>Tips and tricks</h3><p>For Linux users I highly recommend the <strong>pdfunite</strong> command to join PDF files together easily. Also, thisis just one of many CLI tools that are available to users and can significantly simplify your life.</p><p></p>`,Bb="_Newsletter_wx95m_1",Hb="_headerContainer_wx95m_21",Vb="_header_wx95m_21",kb="_form_wx95m_51",Yb="_archive_wx95m_74",Gb="_archiveTitle_wx95m_82",Xb="_folders_wx95m_86",Qb="_emailContent_wx95m_95",Kb="_emaiContentBody_wx95m_102",Ln={Newsletter:Bb,headerContainer:Hb,header:Vb,form:kb,archive:Yb,archiveTitle:Gb,folders:Xb,emailContent:Qb,emaiContentBody:Kb},Zb="/cv_page2/assets/email-BXQuobmo.png";var tr={exports:{}},Ke={},Na={},pl={},Ym;function Ma(){if(Ym)return pl;Ym=1;function r(x){return typeof x>"u"||x===null}function f(x){return typeof x=="object"&&x!==null}function d(x){return Array.isArray(x)?x:r(x)?[]:[x]}function o(x,S){var y,h,b,A;if(S)for(A=Object.keys(S),y=0,h=A.length;y<h;y+=1)b=A[y],x[b]=S[b];return x}function g(x,S){var y="",h;for(h=0;h<S;h+=1)y+=x;return y}function v(x){return x===0&&Number.NEGATIVE_INFINITY===1/x}return pl.isNothing=r,pl.isObject=f,pl.toArray=d,pl.repeat=g,pl.isNegativeZero=v,pl.extend=o,pl}var Ms,Gm;function Vi(){if(Gm)return Ms;Gm=1;function r(f,d){Error.call(this),this.name="YAMLException",this.reason=f,this.mark=d,this.message=(this.reason||"(unknown reason)")+(this.mark?" "+this.mark.toString():""),Error.captureStackTrace?Error.captureStackTrace(this,this.constructor):this.stack=new Error().stack||""}return r.prototype=Object.creat